def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    environment = observation.get("environment_name", "resource_collection")
    grid_width = observation.get("grid_width", 1)
    grid_height = observation.get("grid_height", 1)

    def get_closest_target(targets):
        if not targets:
            return None
        return min(targets, key=lambda pos: abs(pos[0] - sx) + abs(pos[1] - sy))

    def move_towards(target):
        dx, dy = 0, 0
        if target:
            if target[0] > sx:
                dx = 1
            elif target[0] < sx:
                dx = -1
            if target[1] > sy:
                dy = 1
            elif target[1] < sy:
                dy = -1
        return dx, dy

    # Default movement deltas
    dx, dy = 0, 0

    if environment == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            target = (ox, oy)
            dx, dy = move_towards(target)
        else:
            corners = [[0, 0], [0, grid_height - 1], [grid_width - 1, 0], [grid_width - 1, grid_height - 1]]
            target = get_closest_target(corners)
            dx, dy = move_towards(target)

    elif environment == "territory_control":
        targets = (
            observation.get("unclaimed_cells") or
            observation.get("opponent_territory") or
            []
        )
        target = get_closest_target(targets)
        if target:
            dx, dy = move_towards(target)
        else:
            # No target, move randomly
            dx, dy = 0, 0

    else:
        # resource_collection or fallback
        resources = observation.get("resources") or []
        target = get_closest_target(resources)
        if target:
            dx, dy = move_towards(target)
        else:
            # No resource target, move towards opponent or randomly
            if ox != sx:
                dx = 1 if ox > sx else -1
            if oy != sy:
                dy = 1 if oy > sy else -1

    # Ensure dx and dy are each in -1, 0, 1
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]

